<template>
<section><h1>GEO运营数据</h1><p>官网与企业公开主页的第一方统计。站内搜索表现不代表外部推荐。</p><p v-if="error" role="alert">{{ error }}</p>
<div class="tools"><input v-model="q" placeholder="企业名称"/><select v-model="days"><option :value="7">近7天</option><option :value="30">近30天</option><option :value="90">近90天</option></select><button @click="page=1;load()">查询 / 刷新</button></div>
<template v-if="data"><div class="cards"><div>已发布企业<strong>{{ data.published }}</strong></div><div>全部主页浏览<strong>{{ data.metrics.counts.view||0 }}</strong></div><div>联系点击<strong>{{ data.metrics.counts.contact||0 }}</strong></div><div>站内展示<strong>{{ data.metrics.counts.search_impression||0 }}</strong></div></div>
<p>营火官网浏览：{{ data.homepage_metrics.counts.view||0 }} · 企业主页浏览：{{ (data.metrics.counts.view||0)-(data.homepage_metrics.counts.view||0) }}</p><p>{{ data.metrics.definition }} 平台合计包含官网，企业明细不含官网。</p><p v-for="k in ['external_search','model_citations','consultations']" :key="k">{{ data.metrics[k].message }}</p>
<div class="table"><table><thead><tr><th>企业 / 主页</th><th>状态 / 版本</th><th>浏览</th><th>联系点击</th><th>站内展示 / 点击</th><th>管理操作</th></tr></thead><tbody><tr v-for="row in data.items" :key="row.company_id"><td>{{ row.company_name }}<br/><a v-if="row.site.url" :href="row.site.url" target="_blank" rel="noopener">{{ row.site.url }}</a></td><td>{{ labels[row.site.status] }} / {{ row.site.revision }}<br/>{{ row.site.index_status }}</td><td>{{ row.metrics.counts.view||0 }}</td><td>{{ row.metrics.counts.contact||0 }}</td><td>{{ row.metrics.counts.search_impression||0 }} / {{ row.metrics.counts.search_click||0 }}</td><td><button @click="detail=row">查看明细</button><button @click="change(row,'rename')">特殊更名</button><button @click="change(row,row.site.status==='blocked'?'withdrawn':'blocked')">{{ row.site.status==='blocked'?'解除下架':'下架' }}</button></td></tr></tbody></table></div><p v-if="!data.total">暂无企业创建GEO主页</p>
<div class="tools"><button :disabled="page===1" @click="page--;load()">上一页</button><span>{{ page }} / {{ Math.max(1,Math.ceil(data.total/20)) }}</span><button :disabled="page*20>=data.total" @click="page++;load()">下一页</button></div>
<section v-if="detail" class="box"><h2>{{ detail.company_name }} · 明细</h2><p>发布检查：{{ detail.site.issues?.join('；')||'已填写基础资料；请核对来源与时效' }}</p><p>来源：{{ detail.metrics.sources }}</p><p>最近发布时间：{{ detail.site.published_at||'尚未发布' }}</p><pre>{{ detail.metrics.trend }}</pre><button @click="detail=null">收起</button></section>
<h2>公开信息纠错反馈</h2><article class="box" v-for="f in feedback.items" :key="f.id"><p>{{ f.message }}</p><small>{{ f.created_at }} · {{ f.status==='open'?'待处理':'已处理' }} · 站点 {{ f.site_id }}</small><p v-if="f.resolution">处理说明：{{ f.resolution }}</p><button v-if="f.status==='open'" @click="resolve(f.id)">填写处理结果</button></article><p v-if="!feedback.total">暂无纠错反馈</p><div class="tools"><button :disabled="feedbackPage===1" @click="feedbackPage--;loadFeedback()">上一页</button><span>第 {{ feedbackPage }} 页</span><button :disabled="feedbackPage*20>=feedback.total" @click="feedbackPage++;loadFeedback()">下一页</button></div>
<h2>GEO企业主页模板</h2><p>模板与视频创作配置独立。可选择简约、画册或海报布局，配置栏目名称与品牌色新增模板；企业用一张主图和两张展示图排版。已发布资料保留模板配置快照，模板配置升级只在下次发布时生效。</p><div class="tools"><select v-model="selected" @change="selectTemplate"><option value="">新增模板</option><option v-for="t in data.templates" :key="t.code" :value="t.code">{{ t.name }} · v{{ t.revision }}</option></select><button @click="selected='';selectTemplate()">新增</button></div>
<div class="fields"><label>模板标识<input v-model="template.code" :disabled="!!selected"/></label><label>名称<input v-model="template.name"/></label><label>介绍标题<input v-model="template.intro"/></label><label>服务标题<input v-model="template.services"/></label><label>问答标题<input v-model="template.faq"/></label><label>布局风格<select v-model="template.layout"><option value="classic">简约名片</option><option value="editorial">画册展示</option><option value="poster">品牌海报</option></select></label><label>品牌色<input type="color" v-model="template.accent"/></label></div><button @click="saveTemplate">保存并发布模板版本</button>
</template></section>
</template>
<script setup lang="ts">
import {ref,onMounted} from 'vue'
import api from '@/api/client'
const feedback=ref<any>({items:[],total:0}),feedbackPage=ref(1)
const data=ref<any>(null),detail=ref<any>(null),q=ref(''),days=ref(30),page=ref(1),error=ref(''),selected=ref(''),template=ref<any>({})
const labels:Record<string,string>={draft:'未发布',published:'已发布',withdrawn:'已撤回',blocked:'平台下架'}
async function load(){error.value='';try{data.value=(await api.get('/admin/geo',{params:{q:q.value,days:days.value,page:page.value}})).data}catch(e:any){error.value=e.response?.data?.detail||'加载失败'}}
function selectTemplate(){const t=data.value?.templates.find((x:any)=>x.code===selected.value);template.value=t?{code:t.code,name:t.name,expected_revision:t.revision,layout:'classic',...t.config}:{code:'',name:'',intro:'企业介绍',services:'产品与服务',faq:'常见问题',accent:'#c05929',layout:'classic',expected_revision:0}}
async function saveTemplate(){error.value='';try{await api.put('/admin/geo-templates/'+encodeURIComponent(template.value.code),template.value);await load();selected.value=template.value.code;selectTemplate()}catch(e:any){error.value=typeof e.response?.data?.detail==='string'?e.response.data.detail:'模板保存失败'}}
async function change(row:any,kind:string){const reason=prompt('请输入操作原因（至少4字，将记录审计）');if(!reason)return;let payload:any={reason};if(kind==='rename'){const slug=prompt('新网址标识（旧标识永久保留并301跳转）');if(!slug)return;payload.slug=slug}else payload.status=kind;try{await api.post(`/admin/geo/${row.site.id}/change`,payload);await load()}catch(e:any){error.value=e.response?.data?.detail||'操作失败'}}
async function loadFeedback(){try{feedback.value=(await api.get('/admin/geo-feedback',{params:{page:feedbackPage.value}})).data}catch{error.value='反馈读取失败'}}
async function resolve(id:string){const resolution=prompt('填写核实和处理结果（至少4字）');if(!resolution)return;try{await api.post(`/admin/geo-feedback/${id}/resolve`,{resolution});await loadFeedback()}catch{error.value='反馈处理失败'}}
onMounted(async()=>{await load();selectTemplate();await loadFeedback()})
</script>
<style scoped>
input[type=color]{height:42px;padding:4px}.tools{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:20px 0}input,select,button{padding:9px 12px;border:1px solid #cbd3ca;border-radius:6px;background:white;color:#26332f}button{cursor:pointer}.cards{display:flex;gap:20px;flex-wrap:wrap}.cards>div,.box{background:white;border:1px solid #dedfd7;padding:20px;border-radius:12px}.cards strong{display:block;font-size:30px}.table{overflow:auto}table{width:100%;border-collapse:collapse;background:white}th,td{text-align:left;padding:15px;border-bottom:1px solid #ddd}td button{margin:3px}.fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:16px;margin:20px 0}.fields input{display:block;width:100%}pre{max-height:300px;overflow:auto}
</style>
